import { useState } from "react";
import { Navigate, useNavigate } from "react-router-dom";
import { Lock } from "lucide-react";
import { useAuth } from "@/context/AuthContext";
import { formatApiError } from "@/lib/api";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

export default function AdminLogin() {
  const { user, login } = useAuth();
  const nav = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  if (user) return <Navigate to="/admin" replace />;

  const submit = async (e) => {
    e.preventDefault();
    setBusy(true);
    setError("");
    try {
      await login(email, password);
      nav("/admin");
    } catch (err) {
      setError(formatApiError(err));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="min-h-[80vh] grid place-items-center px-5 pt-24" data-testid="admin-login-page">
      <form onSubmit={submit} className="w-full max-w-sm glass rounded-3xl p-8 space-y-5">
        <div className="flex items-center gap-2 font-mono text-xs text-primary"><Lock size={14} /> admin // restricted</div>
        <h1 className="text-2xl font-bold">Sign in</h1>
        <div className="space-y-2"><Label htmlFor="a-email">Email</Label><Input id="a-email" type="email" required value={email} onChange={(e) => setEmail(e.target.value)} data-testid="admin-username-input" /></div>
        <div className="space-y-2"><Label htmlFor="a-pass">Password</Label><Input id="a-pass" type="password" required value={password} onChange={(e) => setPassword(e.target.value)} data-testid="admin-password-input" /></div>
        {error && <p className="text-sm text-destructive" data-testid="admin-login-error">{error}</p>}
        <button type="submit" disabled={busy} className="w-full h-11 rounded-full bg-primary text-primary-foreground font-semibold disabled:opacity-60" data-testid="admin-login-submit-btn">
          {busy ? "Signing in…" : "Sign in"}
        </button>
      </form>
    </div>
  );
}
