import { Link } from "react-router-dom";
import { ArrowUpRight } from "lucide-react";
import { useApp } from "@/context/AppContext";
import { pick } from "@/i18n";
import { Section } from "./Sections";
import { Reveal, Spotlight } from "./motion";
import { ProjectVisual } from "./ProjectVisuals";

export const MitreChip = ({ m }) => (
  <span className="inline-flex items-center gap-1.5 font-mono text-[11px] px-2 py-1 rounded-md border border-primary/25 bg-primary/[0.07] text-accent-foreground" data-testid={`mitre-chip-${m.id}`}>
    <b className="font-semibold text-primary">{m.id}</b><span className="opacity-80">{m.name}</span>
  </span>
);

const ProjectCard = ({ p, i, wide }) => {
  const { t, lang } = useApp();
  return (
    <Reveal delay={i * 0.08} className={wide ? "lg:col-span-2" : ""}>
      <Spotlight as={Link} to={`/projects/${p.slug}`} data-testid={`case-study-card-${i + 1}`}
        className={`group block rounded-3xl glass p-7 sm:p-8 h-full hover:-translate-y-1 transition-transform duration-500 ${wide ? "lg:grid lg:grid-cols-2 lg:gap-10" : ""}`}>
        <div className="rounded-2xl border border-foreground/10 bg-background/40 p-5 mb-7 lg:mb-0 flex flex-col justify-between">
          <div className="flex justify-between font-mono text-[10px] uppercase tracking-wider text-muted-foreground mb-3">
            <span>case_{String(i + 1).padStart(2, "0")}</span><span className="text-primary">● live</span>
          </div>
          <ProjectVisual index={i} />
        </div>
        <div className="flex flex-col">
          <div className="flex items-start justify-between gap-4">
            <h3 className="text-2xl sm:text-3xl font-semibold tracking-tight leading-tight">{pick(p, "title", lang)}</h3>
            <span className="shrink-0 h-10 w-10 rounded-full border border-foreground/10 grid place-items-center group-hover:bg-primary group-hover:text-primary-foreground group-hover:border-primary transition-colors">
              <ArrowUpRight size={17} className="group-hover:rotate-45 transition-transform duration-300" />
            </span>
          </div>
          <p className="text-muted-foreground mt-3 leading-relaxed">{pick(p, "tagline", lang)}</p>
          <div className="flex gap-8 mt-6">
            {p.metrics?.map((m) => (
              <div key={m.label}>
                <div className="text-2xl font-semibold text-gradient-accent">{m.value}</div>
                <div className="text-xs text-muted-foreground mt-0.5">{m.label}</div>
              </div>
            ))}
          </div>
          <div className="flex flex-wrap gap-1.5 mt-6">{p.mitre?.slice(0, 3).map((m) => <MitreChip key={m.id} m={m} />)}</div>
          <span className="mt-6 text-sm font-medium text-primary">{t.readCase} →</span>
        </div>
      </Spotlight>
    </Reveal>
  );
};

export const ProjectsGrid = ({ projects }) => {
  const { t } = useApp();
  return (
    <Section id="projects" label="Case studies" title={t.sections.projects} sub={t.sections.projectsSub} testId="projects-section">
      <div className="grid lg:grid-cols-2 gap-4">
        {projects.map((p, i) => <ProjectCard key={p.slug} p={p} i={i} wide={i === 0} />)}
      </div>
    </Section>
  );
};
