import { useState } from "react";
import { motion } from "framer-motion";
import { ArrowRight, CheckCircle2, Mail, Linkedin, MapPin, Clock } from "lucide-react";
import { useApp } from "@/context/AppContext";
import { api, formatApiError } from "@/lib/api";
import { PROFILE } from "@/i18n";
import { Section } from "./Sections";
import { Reveal } from "./motion";

const EMPTY = { name: "", email: "", company: "", reason: "internship", message: "", website: "" };
const inputCls = "w-full h-11 rounded-xl bg-foreground/[0.03] border border-foreground/10 px-4 text-sm placeholder:text-muted-foreground/60 focus:outline-none focus:border-primary/60 focus:ring-4 focus:ring-primary/10 transition-[border-color,box-shadow]";

const Field = ({ label, children }) => (
  <label className="block space-y-2"><span className="text-xs font-medium text-muted-foreground">{label}</span>{children}</label>
);

export const ContactForm = () => {
  const { t } = useApp();
  const f = t.form;
  const [form, setForm] = useState(EMPTY);
  const [state, setState] = useState("idle");
  const [error, setError] = useState("");
  const set = (k) => (e) => setForm({ ...form, [k]: e.target.value });

  const submit = async (e) => {
    e.preventDefault();
    setState("sending");
    setError("");
    try {
      await api.post("/contact", form);
      setState("sent");
      setForm(EMPTY);
    } catch (err) {
      setError(formatApiError(err) || f.error);
      setState("idle");
    }
  };

  return (
    <Section id="contact" label="Contact" title={t.sections.contact} sub={t.sections.contactSub} testId="contact-section" className="no-print">
      <div className="relative">
        <div className="orb w-[420px] h-[300px] left-1/3 top-10 bg-[hsl(var(--primary)/.18)]" />
        <div className="relative grid lg:grid-cols-[1fr_320px] gap-4">
          <Reveal>
            <div className="rounded-3xl glass p-6 sm:p-9">
              {state === "sent" ? (
                <motion.div initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="py-14 text-center" data-testid="contact-success-message">
                  <CheckCircle2 size={40} className="mx-auto text-[hsl(var(--accent2))]" />
                  <p className="mt-4 text-xl font-semibold">{f.sent}</p>
                </motion.div>
              ) : (
                <form onSubmit={submit} className="grid sm:grid-cols-2 gap-5" data-testid="contact-form">
                  <Field label={f.name}><input required value={form.name} onChange={set("name")} className={inputCls} data-testid="contact-form-name" /></Field>
                  <Field label={f.email}><input type="email" required value={form.email} onChange={set("email")} className={inputCls} data-testid="contact-form-email" /></Field>
                  <Field label={f.company}><input value={form.company} onChange={set("company")} className={inputCls} data-testid="contact-form-company" /></Field>
                  <div className="space-y-2">
                    <span className="text-xs font-medium text-muted-foreground">{f.reason}</span>
                    <div className="flex p-1 rounded-xl bg-foreground/[0.03] border border-foreground/10" data-testid="contact-form-reason">
                      {Object.entries(f.reasons).map(([k, v]) => (
                        <button type="button" key={k} onClick={() => setForm({ ...form, reason: k })} data-testid={`contact-reason-${k}`}
                          className={`relative flex-1 h-9 rounded-lg text-xs sm:text-sm transition-colors ${form.reason === k ? "text-foreground" : "text-muted-foreground hover:text-foreground"}`}>
                          {form.reason === k && <motion.span layoutId="reason-pill" className="absolute inset-0 rounded-lg bg-foreground/10 border border-foreground/10" />}
                          <span className="relative">{v}</span>
                        </button>
                      ))}
                    </div>
                  </div>
                  <div className="sm:col-span-2">
                    <Field label={f.message}><textarea required minLength={10} rows={5} value={form.message} onChange={set("message")} className={`${inputCls} h-auto py-3 resize-none`} data-testid="contact-form-message" /></Field>
                  </div>
                  <input type="text" tabIndex={-1} autoComplete="off" value={form.website} onChange={set("website")} className="hidden" aria-hidden="true" name="website" />
                  {error && <p className="sm:col-span-2 text-sm text-destructive" data-testid="contact-form-error">{error}</p>}
                  <div className="sm:col-span-2">
                    <button type="submit" disabled={state === "sending"} data-testid="contact-form-submit-btn"
                      className="group inline-flex items-center gap-2 h-11 px-6 rounded-full bg-gradient-to-r from-[hsl(var(--primary))] to-[hsl(var(--accent2))] text-[hsl(var(--primary-foreground))] text-sm font-semibold disabled:opacity-60 hover:shadow-[0_0_30px_-4px_hsl(var(--primary)/.7)] transition-shadow">
                      {state === "sending" ? f.sending : f.send}<ArrowRight size={16} className="group-hover:translate-x-0.5 transition-transform" />
                    </button>
                  </div>
                </form>
              )}
            </div>
          </Reveal>
          <Reveal delay={0.1}>
            <div className="rounded-3xl glass p-7 h-full flex flex-col gap-5 text-sm">
              <a href={`mailto:${PROFILE.email}`} className="flex items-center gap-3 hover:text-primary transition-colors break-all" data-testid="contact-email-link"><span className="h-9 w-9 shrink-0 rounded-xl grid place-items-center bg-primary/10 text-primary"><Mail size={16} /></span>{PROFILE.email}</a>
              <a href={PROFILE.linkedin} target="_blank" rel="noreferrer" className="flex items-center gap-3 hover:text-primary transition-colors" data-testid="contact-linkedin-link"><span className="h-9 w-9 shrink-0 rounded-xl grid place-items-center bg-primary/10 text-primary"><Linkedin size={16} /></span>LinkedIn</a>
              <div className="flex items-center gap-3 text-muted-foreground"><span className="h-9 w-9 shrink-0 rounded-xl grid place-items-center bg-foreground/5"><MapPin size={16} /></span>Berlin, Germany</div>
              <div className="flex items-center gap-3 text-muted-foreground"><span className="h-9 w-9 shrink-0 rounded-xl grid place-items-center bg-foreground/5"><Clock size={16} /></span>CET · reply &lt; 24h</div>
            </div>
          </Reveal>
        </div>
      </div>
    </Section>
  );
};
