import { useEffect, useState } from "react";
import { toast } from "sonner";
import { Plus } from "lucide-react";
import { api, formatApiError } from "@/lib/api";
import { PostEditor } from "./PostEditor";

export const PostsPanel = () => {
  const [posts, setPosts] = useState([]);
  const [editing, setEditing] = useState(null);
  const load = () => api.get("/admin/posts").then((r) => setPosts(r.data));
  useEffect(() => { load(); }, []);

  const save = async (data) => {
    try {
      if (data.id) await api.put(`/admin/posts/${data.id}`, data);
      else await api.post("/admin/posts", data);
      toast.success("Post saved");
      setEditing(null);
      load();
    } catch (e) { toast.error(formatApiError(e)); }
  };
  const togglePublish = (p) => save({ ...p, published: !p.published });
  const remove = async (p) => {
    if (!window.confirm(`Delete "${p.title_en}"?`)) return;
    await api.delete(`/admin/posts/${p.id}`);
    load();
  };

  if (editing) return <PostEditor initial={editing} onSave={save} onCancel={() => setEditing(null)} />;
  return (
    <div data-testid="posts-panel">
      <button onClick={() => setEditing({})} className="inline-flex items-center gap-2 h-10 px-4 rounded-md bg-primary text-primary-foreground font-semibold mb-5" data-testid="new-post-btn"><Plus size={16} />New post</button>
      <div className="border rounded-lg divide-y bg-card">
        {posts.map((p) => (
          <div key={p.id} className="p-4 flex flex-wrap items-center justify-between gap-3" data-testid={`admin-post-${p.slug}`}>
            <div>
              <div className="font-semibold">{p.title_en}</div>
              <div className="font-mono text-[11px] text-muted-foreground">/{p.slug} · {p.tags?.join(", ")} · DE: {p.content_de ? "yes" : "no"}</div>
            </div>
            <div className="flex gap-2 items-center">
              <span className={`font-mono text-[11px] uppercase px-2 py-0.5 rounded border ${p.published ? "text-primary border-primary/40" : "text-muted-foreground"}`}>{p.published ? "published" : "draft"}</span>
              <button onClick={() => togglePublish(p)} className="text-xs border rounded h-8 px-3" data-testid={`toggle-publish-${p.slug}`}>{p.published ? "Unpublish" : "Publish"}</button>
              <button onClick={() => setEditing(p)} className="text-xs border rounded h-8 px-3" data-testid={`edit-post-${p.slug}`}>Edit</button>
              <button onClick={() => remove(p)} className="text-xs border rounded h-8 px-3 text-destructive" data-testid={`delete-post-${p.slug}`}>Delete</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};
