import { Link } from "react-router-dom";
import { useEffect, useState } from "react";
import { Menu, X, Moon, Sun, Languages } from "lucide-react";
import { useApp } from "@/context/AppContext";

const NAV = [
  ["projects", "/#projects"],
  ["experience", "/#experience"],
  ["certs", "/#certs"],
  ["blog", "/blog"],
  ["contact", "/#contact"],
];

const Controls = () => {
  const { theme, toggleTheme, lang, toggleLang } = useApp();
  const btn = "h-8 inline-flex items-center gap-1.5 px-2.5 rounded-full text-xs text-muted-foreground hover:text-foreground hover:bg-foreground/5 transition-colors";
  return (
    <div className="flex items-center gap-1">
      <button onClick={toggleLang} data-testid="language-switch-button" className={`${btn} font-mono uppercase`} aria-label="Switch language">
        <Languages size={14} />{lang === "en" ? "EN" : "DE"}
      </button>
      <button onClick={toggleTheme} data-testid="theme-toggle-button" aria-label="Toggle theme" className={btn}>
        {theme === "dark" ? <Sun size={15} /> : <Moon size={15} />}
      </button>
    </div>
  );
};

export const Header = () => {
  const { t } = useApp();
  const [open, setOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  useEffect(() => {
    const on = () => setScrolled(window.scrollY > 12);
    window.addEventListener("scroll", on);
    return () => window.removeEventListener("scroll", on);
  }, []);

  return (
    <header className="no-print fixed top-0 inset-x-0 z-50 px-3 sm:px-6 pt-3">
      <div className={`max-w-6xl mx-auto h-14 px-4 sm:px-5 flex items-center justify-between gap-4 rounded-2xl transition-[background-color,border-color,box-shadow] duration-300 ${scrolled || open ? "glass shadow-[0_8px_30px_-12px_rgba(0,0,0,.35)]" : "border border-transparent"}`}>
        <Link to="/" data-testid="header-brand-logo" className="flex items-center gap-2.5">
          <span className="h-7 w-7 rounded-lg bg-gradient-to-br from-[hsl(var(--primary))] to-[hsl(var(--accent2))] grid place-items-center font-mono text-[11px] font-bold text-[hsl(var(--primary-foreground))]">KV</span>
          <span className="font-semibold tracking-tight whitespace-nowrap">Kundan Vidhate</span>
        </Link>
        <nav className="hidden md:flex items-center gap-1">
          {NAV.map(([k, href]) => (
            <Link key={k} to={href} data-testid={`nav-${k}-link`} className="whitespace-nowrap px-3 py-1.5 rounded-full text-sm text-muted-foreground hover:text-foreground hover:bg-foreground/5 transition-colors">
              {t.nav[k]}
            </Link>
          ))}
        </nav>
        <div className="flex items-center gap-2">
          <span className="hidden lg:inline-flex items-center gap-2 whitespace-nowrap rounded-full border border-[hsl(var(--accent2)/.35)] bg-[hsl(var(--accent2)/.08)] px-2.5 py-1 text-[11px] font-medium text-[hsl(var(--accent2))]" data-testid="header-availability">
            <span className="h-1.5 w-1.5 rounded-full bg-[hsl(var(--accent2))] pulse-dot" />{t.status}
          </span>
          <Controls />
          <button className="md:hidden h-8 w-8 grid place-items-center rounded-full hover:bg-foreground/5" onClick={() => setOpen(!open)} data-testid="mobile-menu-button">
            {open ? <X size={16} /> : <Menu size={16} />}
          </button>
        </div>
      </div>
      {open && (
        <nav className="md:hidden max-w-6xl mx-auto mt-2 glass rounded-2xl p-3 flex flex-col" data-testid="mobile-menu">
          {NAV.map(([k, href]) => (
            <Link key={k} to={href} onClick={() => setOpen(false)} className="px-3 py-2.5 rounded-lg hover:bg-foreground/5" data-testid={`mobile-nav-${k}-link`}>{t.nav[k]}</Link>
          ))}
        </nav>
      )}
    </header>
  );
};
