import { useEffect, useState } from "react";
import { motion } from "framer-motion";
import { api } from "@/lib/api";
import { useApp } from "@/context/AppContext";
import { PostRow } from "@/components/site/BlogCards";
import { Reveal, Eyebrow } from "@/components/site/motion";

const TAGS = ["Detection", "CTF", "Lab", "Compliance"];

export default function BlogList() {
  const { t } = useApp();
  const b = t.blogPage;
  const [posts, setPosts] = useState(null);
  const [tag, setTag] = useState(null);
  useEffect(() => {
    api.get("/posts", { params: tag ? { tag } : {} }).then((r) => setPosts(r.data));
  }, [tag]);

  return (
    <div className="relative max-w-5xl mx-auto px-5 sm:px-8 pt-32" data-testid="blog-list-page">
      <div className="orb w-[500px] h-[360px] -top-24 right-0 bg-[hsl(var(--accent2)/.12)]" />
      <Reveal className="relative">
        <Eyebrow>Blog</Eyebrow>
        <h1 className="mt-5 text-5xl sm:text-6xl font-semibold text-gradient">{b.title}</h1>
        <p className="text-lg text-muted-foreground mt-4 max-w-xl">{b.sub}</p>
      </Reveal>
      <div className="relative inline-flex flex-wrap gap-1 mt-10 mb-8 p-1 rounded-full glass" data-testid="blog-tag-filters">
        {[null, ...TAGS].map((tg) => (
          <button key={tg || "all"} onClick={() => setTag(tg)} data-testid={`blog-tag-${tg || "all"}`}
            className={`relative h-8 px-4 rounded-full text-sm transition-colors ${tag === tg ? "text-foreground" : "text-muted-foreground hover:text-foreground"}`}>
            {tag === tg && <motion.span layoutId="tag-pill" className="absolute inset-0 rounded-full bg-foreground/10" />}
            <span className="relative">{tg || b.all}</span>
          </button>
        ))}
      </div>
      <div className="relative grid md:grid-cols-2 gap-3">
        {posts?.map((p, i) => <Reveal key={p.slug} delay={i * 0.06}><PostRow p={p} /></Reveal>)}
      </div>
      {posts?.length === 0 && <p className="py-10 text-muted-foreground" data-testid="blog-empty">{b.empty}</p>}
    </div>
  );
}
