import { Link } from "react-router-dom";
import { ArrowUpRight } from "lucide-react";
import { useApp } from "@/context/AppContext";
import { pick, readingTime } from "@/i18n";
import { Spotlight } from "./motion";

export const TagChip = ({ tag }) => (
  <span className="text-[11px] px-2 py-0.5 rounded-full border border-primary/25 bg-primary/[0.07] text-primary">{tag}</span>
);

export const PostRow = ({ p }) => {
  const { lang, t } = useApp();
  return (
    <Spotlight as={Link} to={`/blog/${p.slug}`} data-testid={`post-row-${p.slug}`}
      className="group block rounded-2xl glass p-6 hover:-translate-y-0.5 transition-transform duration-300">
      <div className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
        <span className="font-mono">{new Date(p.created_at).toLocaleDateString(lang === "de" ? "de-DE" : "en-GB", { year: "numeric", month: "short", day: "2-digit" })}</span>
        {p.tags?.map((tg) => <TagChip key={tg} tag={tg} />)}
      </div>
      <div className="flex items-start justify-between gap-4 mt-3">
        <h3 className="text-lg sm:text-xl font-semibold tracking-tight leading-snug group-hover:text-primary transition-colors">{pick(p, "title", lang)}</h3>
        <ArrowUpRight size={18} className="shrink-0 text-muted-foreground group-hover:text-primary group-hover:rotate-45 transition-[transform,color] duration-300" />
      </div>
      <p className="text-sm text-muted-foreground mt-2 leading-relaxed">{pick(p, "excerpt", lang)}</p>
      {p.content_en === undefined && <span className="sr-only">{t.minRead}</span>}
      {p.content_en && <span className="mt-3 block font-mono text-[11px] text-muted-foreground">{readingTime(p.content_en)} {t.minRead}</span>}
    </Spotlight>
  );
};
