import { useState } from "react";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Markdown } from "@/components/site/Markdown";

const TAGS = ["Detection", "CTF", "Lab", "Compliance"];
const BASE = { title_en: "", title_de: "", excerpt_en: "", excerpt_de: "", content_en: "", content_de: "", tags: [], published: false };

export const PostEditor = ({ initial, onSave, onCancel }) => {
  const [f, setF] = useState({ ...BASE, ...initial });
  const [lang, setLang] = useState("en");
  const set = (k) => (e) => setF({ ...f, [k]: e.target.value });
  const toggleTag = (t) => setF({ ...f, tags: f.tags.includes(t) ? f.tags.filter((x) => x !== t) : [...f.tags, t] });

  return (
    <form onSubmit={(e) => { e.preventDefault(); onSave(f); }} className="space-y-5" data-testid="post-editor">
      <div className="flex gap-2">
        {["en", "de"].map((l) => (
          <button type="button" key={l} onClick={() => setLang(l)} data-testid={`editor-lang-${l}`}
            className={`font-mono text-xs h-8 px-3 rounded-md border uppercase ${lang === l ? "border-primary bg-accent" : ""}`}>{l}</button>
        ))}
        <span className="text-xs text-muted-foreground self-center ml-2">German is optional — falls back to English.</span>
      </div>
      <div className="space-y-2"><Label>Title ({lang})</Label><Input required={lang === "en"} value={f[`title_${lang}`]} onChange={set(`title_${lang}`)} data-testid={`post-title-${lang}-input`} /></div>
      <div className="space-y-2"><Label>Excerpt ({lang})</Label><Input value={f[`excerpt_${lang}`]} onChange={set(`excerpt_${lang}`)} data-testid={`post-excerpt-${lang}-input`} /></div>
      <div className="grid lg:grid-cols-2 gap-4">
        <div className="space-y-2"><Label>Content ({lang}, Markdown)</Label><Textarea rows={16} className="font-mono text-xs" value={f[`content_${lang}`]} onChange={set(`content_${lang}`)} data-testid={`post-content-${lang}-input`} /></div>
        <div className="space-y-2"><Label>Preview</Label><div className="border rounded-md p-4 h-[340px] overflow-auto bg-background"><Markdown>{f[`content_${lang}`]}</Markdown></div></div>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        {TAGS.map((t) => (
          <button type="button" key={t} onClick={() => toggleTag(t)} data-testid={`post-tag-${t}`}
            className={`font-mono text-xs h-8 px-3 rounded-md border ${f.tags.includes(t) ? "border-primary bg-accent text-accent-foreground" : ""}`}>{t}</button>
        ))}
        <label className="flex items-center gap-2 ml-4 text-sm"><Switch checked={f.published} onCheckedChange={(v) => setF({ ...f, published: v })} data-testid="post-published-switch" />Published</label>
      </div>
      <div className="flex gap-3">
        <button type="submit" disabled={!f.title_en || !f.content_en} className="h-10 px-5 rounded-md bg-primary text-primary-foreground font-semibold disabled:opacity-50" data-testid="post-save-btn">Save</button>
        <button type="button" onClick={onCancel} className="h-10 px-5 rounded-md border" data-testid="post-cancel-btn">Cancel</button>
      </div>
    </form>
  );
};
