import { useEffect, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";

const EVENTS = [
  { sev: "CRIT", rule: "LSASS memory access", src: "WIN10-LAB", tech: "T1003.001" },
  { sev: "HIGH", rule: "SSH brute force · 12 fails/120s", src: "10.0.4.7", tech: "T1110" },
  { sev: "MED", rule: "Encoded PowerShell executed", src: "WIN10-LAB", tech: "T1059.001" },
  { sev: "HIGH", rule: "Known-bad hash · VT 9/70", src: "mail-gw", tech: "T1204" },
  { sev: "LOW", rule: "Duplicate merged → case #482", src: "soar", tech: "—" },
  { sev: "MED", rule: "New local admin added", src: "SRV-02", tech: "T1136.001" },
  { sev: "HIGH", rule: "Impossible travel · DE → SG", src: "j.doe", tech: "T1078" },
  { sev: "LOW", rule: "Triage conf 0.54 → manual review", src: "ai-l1", tech: "—" },
];
const SEV = {
  CRIT: "text-[hsl(var(--danger))] bg-[hsl(var(--danger)/.12)] border-[hsl(var(--danger)/.3)]",
  HIGH: "text-[hsl(var(--warn))] bg-[hsl(var(--warn)/.12)] border-[hsl(var(--warn)/.3)]",
  MED: "text-primary bg-primary/10 border-primary/30",
  LOW: "text-muted-foreground bg-foreground/5 border-foreground/10",
};

const stamp = () => new Date().toLocaleTimeString("de-DE", { hour12: false });

export const AlertConsole = () => {
  const [rows, setRows] = useState(() => EVENTS.slice(0, 5).map((e, i) => ({ ...e, id: i, time: stamp() })));
  const [count, setCount] = useState(1284);
  useEffect(() => {
    let i = 5;
    const id = setInterval(() => {
      const e = EVENTS[i % EVENTS.length];
      setRows((r) => [{ ...e, id: i, time: stamp() }, ...r].slice(0, 5));
      setCount((c) => c + 1);
      i += 1;
    }, 2200);
    return () => clearInterval(id);
  }, []);

  return (
    <div className="relative glass rounded-2xl overflow-hidden shadow-[0_30px_80px_-30px_rgba(0,0,0,.6)]" data-testid="alert-console">
      <div className="absolute inset-x-0 h-16 bg-gradient-to-b from-primary/10 to-transparent scanline pointer-events-none" />
      <div className="flex items-center justify-between px-4 h-11 border-b border-foreground/10">
        <div className="flex items-center gap-2">
          <span className="flex gap-1.5"><i className="h-2.5 w-2.5 rounded-full bg-foreground/15" /><i className="h-2.5 w-2.5 rounded-full bg-foreground/15" /><i className="h-2.5 w-2.5 rounded-full bg-foreground/15" /></span>
          <span className="font-mono text-[11px] text-muted-foreground ml-2">wazuh · live-alerts</span>
        </div>
        <span className="flex items-center gap-1.5 font-mono text-[11px] text-[hsl(var(--accent2))]"><span className="h-1.5 w-1.5 rounded-full bg-[hsl(var(--accent2))] pulse-dot" />streaming</span>
      </div>
      <div className="grid grid-cols-3 border-b border-foreground/10 font-mono">
        {[["events/24h", count.toLocaleString("en")], ["mttd", "42s"], ["open cases", "3"]].map(([k, v]) => (
          <div key={k} className="px-4 py-3 border-r last:border-r-0 border-foreground/10">
            <div className="text-[10px] uppercase tracking-wider text-muted-foreground">{k}</div>
            <div className="text-lg font-semibold mt-0.5">{v}</div>
          </div>
        ))}
      </div>
      <ul className="p-2 font-mono text-[12px] h-[248px] overflow-hidden">
        <AnimatePresence initial={false}>
          {rows.map((r) => (
            <motion.li key={r.id} layout initial={{ opacity: 0, y: -14, backgroundColor: "hsla(188,94%,55%,0.10)" }}
              animate={{ opacity: 1, y: 0, backgroundColor: "hsla(188,94%,55%,0)" }} exit={{ opacity: 0 }}
              transition={{ duration: 0.5 }} className="flex items-center gap-3 px-2.5 py-2.5 rounded-lg">
              <span className="text-muted-foreground w-[60px] shrink-0">{r.time}</span>
              <span className={`w-[44px] shrink-0 text-center text-[10px] font-semibold rounded border py-0.5 ${SEV[r.sev]}`}>{r.sev}</span>
              <span className="truncate flex-1">{r.rule}</span>
              <span className="hidden sm:inline text-muted-foreground shrink-0">{r.tech}</span>
            </motion.li>
          ))}
        </AnimatePresence>
      </ul>
    </div>
  );
};
