import { useEffect, useState } from "react";
import { toast } from "sonner";
import { api, formatApiError } from "@/lib/api";

const FILTERS = ["new", "read", "archived", "all"];

export const MessagesPanel = () => {
  const [msgs, setMsgs] = useState([]);
  const [filter, setFilter] = useState("new");
  const load = () => api.get("/admin/messages").then((r) => setMsgs(r.data));
  useEffect(() => { load(); }, []);

  const setStatus = async (id, status) => {
    try {
      await api.patch(`/admin/messages/${id}`, { status });
      setMsgs((m) => m.map((x) => (x.id === id ? { ...x, status } : x)));
    } catch (e) { toast.error(formatApiError(e)); }
  };
  const shown = msgs.filter((m) => filter === "all" || m.status === filter);

  return (
    <div data-testid="messages-panel">
      <div className="flex gap-2 mb-5">
        {FILTERS.map((f) => (
          <button key={f} onClick={() => setFilter(f)} data-testid={`messages-filter-${f}`}
            className={`font-mono text-xs h-8 px-3 rounded-md border capitalize ${filter === f ? "border-primary bg-accent text-accent-foreground" : ""}`}>
            {f} ({f === "all" ? msgs.length : msgs.filter((m) => m.status === f).length})
          </button>
        ))}
      </div>
      {shown.length === 0 && <p className="text-muted-foreground py-8" data-testid="messages-empty">No messages here.</p>}
      <div className="space-y-3">
        {shown.map((m) => (
          <div key={m.id} className="border rounded-lg bg-card p-5" data-testid={`message-item-${m.id}`}>
            <div className="flex flex-wrap justify-between gap-2">
              <div>
                <span className="font-semibold">{m.name}</span>
                <span className="text-muted-foreground text-sm"> · {m.email}{m.company && ` · ${m.company}`}</span>
              </div>
              <div className="flex items-center gap-2 font-mono text-[11px]">
                <span className="uppercase px-2 py-0.5 rounded border">{m.reason}</span>
                <span className="text-muted-foreground">{new Date(m.created_at).toLocaleString()}</span>
              </div>
            </div>
            <p className="mt-3 text-sm whitespace-pre-wrap">{m.message}</p>
            <div className="flex gap-2 mt-4">
              {m.status !== "read" && <button onClick={() => setStatus(m.id, "read")} className="text-xs border rounded h-8 px-3 hover:border-primary" data-testid={`message-mark-read-${m.id}`}>Mark read</button>}
              {m.status !== "archived" && <button onClick={() => setStatus(m.id, "archived")} className="text-xs border rounded h-8 px-3 hover:border-primary" data-testid={`message-archive-${m.id}`}>Archive</button>}
              {m.status !== "new" && <button onClick={() => setStatus(m.id, "new")} className="text-xs border rounded h-8 px-3 hover:border-primary" data-testid={`message-mark-new-${m.id}`}>Mark new</button>}
              <a href={`mailto:${m.email}`} className="text-xs border rounded h-8 px-3 grid place-items-center hover:border-primary" data-testid={`message-reply-${m.id}`}>Reply</a>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};
