import { Outlet, useLocation, Link } from "react-router-dom";
import { useEffect } from "react";
import { Github, Linkedin } from "lucide-react";
import { Header } from "./Header";
import { useApp } from "@/context/AppContext";
import { PROFILE } from "@/i18n";

export const SiteLayout = () => {
  const { pathname, hash } = useLocation();
  const { t } = useApp();
  useEffect(() => {
    if (hash) setTimeout(() => document.getElementById(hash.slice(1))?.scrollIntoView({ behavior: "smooth" }), 60);
    else window.scrollTo(0, 0);
  }, [pathname, hash]);

  return (
    <div className="min-h-screen flex flex-col overflow-x-clip">
      <Header />
      <main className="flex-1"><Outlet /></main>
      <footer className="no-print mt-32 border-t" data-testid="site-footer">
        <div className="max-w-6xl mx-auto px-5 sm:px-8 py-10 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-5">
          <div className="flex items-center gap-3">
            <span className="h-7 w-7 rounded-lg bg-gradient-to-br from-[hsl(var(--primary))] to-[hsl(var(--accent2))] grid place-items-center font-mono text-[11px] font-bold text-[hsl(var(--primary-foreground))]">KV</span>
            <span className="text-sm text-muted-foreground">{t.footer}</span>
          </div>
          <div className="flex items-center gap-5 text-sm text-muted-foreground">
            <a href={PROFILE.linkedin} target="_blank" rel="noreferrer" className="hover:text-foreground transition-colors" aria-label="LinkedIn"><Linkedin size={17} /></a>
            <a href={PROFILE.github} target="_blank" rel="noreferrer" className="hover:text-foreground transition-colors" aria-label="GitHub"><Github size={17} /></a>
            <Link to="/admin/login" className="hover:text-foreground transition-colors" data-testid="footer-admin-link">Admin</Link>
          </div>
        </div>
      </footer>
    </div>
  );
};
