import { useEffect, useState } from "react";
import { motion } from "framer-motion";
import { Download, ArrowRight, Linkedin, Github } from "lucide-react";
import { useApp } from "@/context/AppContext";
import { PROFILE } from "@/i18n";
import { AlertConsole } from "./AlertConsole";

const VERBS = { en: ["detect.", "triage.", "automate.", "respond."], de: ["erkenne.", "triagiere.", "automatisiere.", "reagiere."] };

const Typer = () => {
  const { lang } = useApp();
  const words = VERBS[lang];
  const [i, setI] = useState(0);
  const [txt, setTxt] = useState("");
  useEffect(() => {
    const w = words[i % words.length];
    if (txt.length < w.length) {
      const id = setTimeout(() => setTxt(w.slice(0, txt.length + 1)), 70);
      return () => clearTimeout(id);
    }
    const id = setTimeout(() => { setTxt(""); setI(i + 1); }, 1800);
    return () => clearTimeout(id);
  }, [txt, i, words]);
  return <span className="text-gradient-accent caret" data-testid="hero-typer">{txt}</span>;
};

const up = (d) => ({ initial: { opacity: 0, y: 20 }, animate: { opacity: 1, y: 0 }, transition: { duration: 0.8, delay: d, ease: [0.16, 1, 0.3, 1] } });

const Facts = ({ h }) => (
  <motion.div {...up(0.6)} className="mt-16 glass rounded-2xl grid grid-cols-2 lg:grid-cols-5 divide-x divide-y lg:divide-y-0 divide-foreground/10 overflow-hidden" data-testid="recruiter-summary-card">
    {[["role", h.role, h.roleV], ["availability", h.avail, h.availV], ["locations", h.loc, h.locV], ["status", h.status, h.statusV], ["languages", h.lang, h.langV]].map(([id, k, v]) => (
      <div key={id} className="p-5 last:col-span-2 lg:last:col-span-1" data-testid={`recruiter-summary-${id}`}>
        <div className="font-mono text-[10px] uppercase tracking-[0.14em] text-muted-foreground">{k}</div>
        <div className="text-sm font-medium mt-1.5 leading-snug">{v}</div>
      </div>
    ))}
  </motion.div>
);

export const Hero = () => {
  const { t, lang } = useApp();
  const h = t.hero;
  return (
    <section className="relative pt-32 lg:pt-40 pb-10 overflow-hidden" data-testid="hero-section">
      <div className="absolute inset-0 bg-grid pointer-events-none" />
      <div className="orb drift w-[520px] h-[520px] -top-40 -left-32 bg-[hsl(var(--primary)/.22)]" />
      <div className="orb drift w-[460px] h-[460px] top-20 right-[-120px] bg-[hsl(var(--accent2)/.16)]" style={{ animationDelay: "-6s" }} />
      <div className="relative max-w-6xl mx-auto px-5 sm:px-8">
        <div className="grid grid-cols-1 lg:grid-cols-[1.1fr_1fr] gap-12 lg:gap-14 items-center">
          <div>
            <motion.a {...up(0)} href="#contact" className="inline-flex items-center gap-2 rounded-full glass shine-border pl-1.5 pr-3.5 py-1 text-xs" data-testid="hero-availability-pill">
              <span className="rounded-full bg-[hsl(var(--accent2)/.15)] text-[hsl(var(--accent2))] px-2 py-0.5 font-medium">{lang === "de" ? "Offen für Angebote" : "Open to work"}</span>
              <span className="text-muted-foreground">{h.availV.split("(")[0]}· DE · NL · BE · IE</span>
            </motion.a>
            <motion.p {...up(0.08)} className="mt-7 font-mono text-xs uppercase tracking-[0.18em] text-primary">{h.eyebrow}</motion.p>
            <motion.h1 {...up(0.14)} className="mt-3 text-5xl sm:text-6xl lg:text-7xl font-semibold leading-[1.02]">
              <span className="text-gradient">Kundan Vidhate</span>
            </motion.h1>
            <motion.p {...up(0.22)} className="mt-5 text-2xl sm:text-3xl font-medium tracking-tight">
              {lang === "de" ? "Ich" : "I"} <Typer />
            </motion.p>
            <motion.p {...up(0.3)} className="mt-5 text-muted-foreground max-w-xl leading-relaxed">{h.lead}</motion.p>
            <motion.div {...up(0.38)} className="mt-9 flex flex-wrap items-center gap-3">
              <a href={PROFILE.cv} download data-testid="recruiter-download-cv-btn"
                className="group inline-flex items-center gap-2 h-11 px-5 rounded-full bg-foreground text-background text-sm font-medium hover:shadow-[0_0_0_4px_hsl(var(--primary)/.25)] transition-shadow">
                <Download size={16} className="group-hover:translate-y-0.5 transition-transform" />{h.cv}
              </a>
              <a href="#contact" data-testid="recruiter-contact-btn" className="group inline-flex items-center gap-2 h-11 px-5 rounded-full glass text-sm font-medium hover:border-primary/50 transition-colors">
                {h.contact}<ArrowRight size={15} className="group-hover:translate-x-0.5 transition-transform" />
              </a>
              <a href={PROFILE.linkedin} target="_blank" rel="noreferrer" aria-label="LinkedIn" data-testid="hero-linkedin-link" className="h-11 w-11 grid place-items-center rounded-full glass hover:text-primary transition-colors"><Linkedin size={16} /></a>
              <a href={PROFILE.github} target="_blank" rel="noreferrer" aria-label="GitHub" data-testid="hero-github-link" className="h-11 w-11 grid place-items-center rounded-full glass hover:text-primary transition-colors"><Github size={16} /></a>
            </motion.div>
          </div>
          <motion.div initial={{ opacity: 0, y: 30, rotateX: 12 }} animate={{ opacity: 1, y: 0, rotateX: 0 }} transition={{ duration: 1, delay: 0.3, ease: [0.16, 1, 0.3, 1] }} style={{ perspective: 1000 }}>
            <AlertConsole />
          </motion.div>
        </div>
        <Facts h={h} />
      </div>
    </section>
  );
};
