import { createContext, useContext, useEffect, useState } from "react";
import { STRINGS } from "@/i18n";

const AppCtx = createContext(null);

const initialTheme = () => {
  const saved = localStorage.getItem("kv-theme");
  return saved || "dark";
};

export const AppProvider = ({ children }) => {
  const [theme, setTheme] = useState(initialTheme);
  const [lang, setLang] = useState(() => localStorage.getItem("kv-lang") || "en");

  useEffect(() => {
    document.documentElement.classList.toggle("dark", theme === "dark");
  }, [theme]);
  useEffect(() => {
    document.documentElement.lang = lang;
  }, [lang]);

  const toggleTheme = () => {
    const next = theme === "dark" ? "light" : "dark";
    localStorage.setItem("kv-theme", next);
    setTheme(next);
  };
  const toggleLang = () => {
    const next = lang === "en" ? "de" : "en";
    localStorage.setItem("kv-lang", next);
    setLang(next);
  };

  return (
    <AppCtx.Provider value={{ theme, toggleTheme, lang, toggleLang, t: STRINGS[lang] }}>
      {children}
    </AppCtx.Provider>
  );
};

export const useApp = () => useContext(AppCtx);
