import { useState } from "react";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";

const TEXT_FIELDS = ["title", "tagline", "problem", "architecture", "outcome"];
const toLines = (arr, a, b) => arr.map((x) => `${x[a]} | ${x[b]}`).join("\n");
const fromLines = (s, a, b) => s.split("\n").map((l) => l.split("|").map((x) => x.trim())).filter(([x]) => x).map(([x, ...rest]) => ({ [a]: x, [b]: rest.join(" | ") }));

export const ProjectEditor = ({ initial, onSave, onCancel }) => {
  const [f, setF] = useState(initial);
  const [lang, setLang] = useState("en");
  const [lists, setLists] = useState({
    detections: toLines(initial.detections || [], "name", "logic"),
    mitre: toLines(initial.mitre || [], "id", "name"),
    metrics: toLines(initial.metrics || [], "value", "label"),
    stack: (initial.stack || []).join(", "),
  });
  const set = (k) => (e) => setF({ ...f, [k]: e.target.value });
  const setList = (k) => (e) => setLists({ ...lists, [k]: e.target.value });

  const submit = (e) => {
    e.preventDefault();
    const { slug, _id, created_at, updated_at, ...rest } = f;
    onSave(slug, {
      ...rest,
      detections: fromLines(lists.detections, "name", "logic"),
      mitre: fromLines(lists.mitre, "id", "name"),
      metrics: fromLines(lists.metrics, "value", "label"),
      stack: lists.stack.split(",").map((s) => s.trim()).filter(Boolean),
    });
  };

  return (
    <form onSubmit={submit} className="space-y-5" data-testid="project-editor">
      <div className="flex gap-2">
        {["en", "de"].map((l) => (
          <button type="button" key={l} onClick={() => setLang(l)} data-testid={`project-editor-lang-${l}`}
            className={`font-mono text-xs h-8 px-3 rounded-md border uppercase ${lang === l ? "border-primary bg-accent" : ""}`}>{l}</button>
        ))}
      </div>
      {TEXT_FIELDS.map((k) => (
        <div key={k} className="space-y-2">
          <Label className="capitalize">{k} ({lang})</Label>
          {k === "title" || k === "tagline"
            ? <Input value={f[`${k}_${lang}`] || ""} onChange={set(`${k}_${lang}`)} data-testid={`project-${k}-${lang}-input`} />
            : <Textarea rows={4} value={f[`${k}_${lang}`] || ""} onChange={set(`${k}_${lang}`)} data-testid={`project-${k}-${lang}-input`} />}
        </div>
      ))}
      <div className="grid md:grid-cols-2 gap-4">
        <div className="space-y-2"><Label>Detections (name | logic, one per line)</Label><Textarea rows={5} className="font-mono text-xs" value={lists.detections} onChange={setList("detections")} data-testid="project-detections-input" /></div>
        <div className="space-y-2"><Label>MITRE (ID | name, one per line)</Label><Textarea rows={5} className="font-mono text-xs" value={lists.mitre} onChange={setList("mitre")} data-testid="project-mitre-input" /></div>
        <div className="space-y-2"><Label>Metrics (value | label)</Label><Textarea rows={3} className="font-mono text-xs" value={lists.metrics} onChange={setList("metrics")} data-testid="project-metrics-input" /></div>
        <div className="space-y-2"><Label>Stack (comma separated)</Label><Input value={lists.stack} onChange={setList("stack")} data-testid="project-stack-input" />
          <Label className="block pt-2">GitHub URL</Label><Input value={f.github || ""} onChange={set("github")} data-testid="project-github-input" /></div>
      </div>
      <div className="flex gap-3">
        <button type="submit" className="h-10 px-5 rounded-md bg-primary text-primary-foreground font-semibold" data-testid="project-save-btn">Save</button>
        <button type="button" onClick={onCancel} className="h-10 px-5 rounded-md border" data-testid="project-cancel-btn">Cancel</button>
      </div>
    </form>
  );
};
