import { useEffect, useState } from "react";
import { toast } from "sonner";
import { api, formatApiError } from "@/lib/api";
import { ProjectEditor } from "./ProjectEditor";

export const ProjectsPanel = () => {
  const [projects, setProjects] = useState([]);
  const [editing, setEditing] = useState(null);
  const load = () => api.get("/projects").then((r) => setProjects(r.data));
  useEffect(() => { load(); }, []);

  const save = async (slug, data) => {
    try {
      await api.put(`/projects/${slug}`, data);
      toast.success("Case study saved");
      setEditing(null);
      load();
    } catch (e) { toast.error(formatApiError(e)); }
  };

  if (editing) return <ProjectEditor initial={editing} onSave={save} onCancel={() => setEditing(null)} />;
  return (
    <div className="border rounded-lg divide-y bg-card" data-testid="projects-panel">
      {projects.map((p) => (
        <div key={p.slug} className="p-4 flex items-center justify-between gap-3" data-testid={`admin-project-${p.slug}`}>
          <div>
            <div className="font-semibold">{p.title_en}</div>
            <div className="font-mono text-[11px] text-muted-foreground">/projects/{p.slug}</div>
          </div>
          <button onClick={() => setEditing(p)} className="text-xs border rounded h-8 px-3" data-testid={`edit-project-${p.slug}`}>Edit</button>
        </div>
      ))}
    </div>
  );
};
