import { useEffect, useState } from "react";
import { Link, useParams } from "react-router-dom";
import { ArrowLeft } from "lucide-react";
import { api } from "@/lib/api";
import { useApp } from "@/context/AppContext";
import { pick, readingTime } from "@/i18n";
import { Markdown } from "@/components/site/Markdown";
import { TagChip } from "@/components/site/BlogCards";

export default function BlogPost() {
  const { slug } = useParams();
  const { t, lang } = useApp();
  const [p, setP] = useState(null);
  const [missing, setMissing] = useState(false);
  useEffect(() => {
    api.get(`/posts/${slug}`).then((r) => setP(r.data)).catch(() => setMissing(true));
  }, [slug]);

  if (missing) return <div className="max-w-3xl mx-auto px-5 pt-40" data-testid="post-not-found">404 — <Link to="/blog" className="text-primary">{t.back}</Link></div>;
  if (!p) return <div className="max-w-3xl mx-auto px-5 pt-40 font-mono text-sm text-muted-foreground">loading…</div>;

  const content = pick(p, "content", lang);
  const fallback = lang === "de" && !p.content_de;
  return (
    <article className="max-w-3xl mx-auto px-5 sm:px-8 pt-32" data-testid="blog-post-page">
      <Link to="/blog" className="no-print inline-flex items-center gap-2 h-9 px-4 rounded-full glass text-sm hover:text-primary transition-colors mb-10" data-testid="post-back-link"><ArrowLeft size={15} />{t.back}</Link>
      <div className="flex flex-wrap items-center gap-3 font-mono text-xs text-muted-foreground mb-4">
        <span>{new Date(p.created_at).toLocaleDateString(lang === "de" ? "de-DE" : "en-GB", { dateStyle: "medium" })}</span>
        <span>·</span>
        <span data-testid="post-reading-time">{readingTime(content)} {t.minRead}</span>
        {p.tags?.map((tg) => <TagChip key={tg} tag={tg} />)}
      </div>
      <h1 className="text-4xl sm:text-5xl font-semibold leading-[1.08] text-gradient" data-testid="post-title">{pick(p, "title", lang)}</h1>
      {fallback && <p className="mt-6 text-sm border-l-2 border-[hsl(var(--warn))] pl-3 text-muted-foreground" data-testid="post-lang-fallback">{t.blogPage.fallback}</p>}
      <div className="mt-10"><Markdown>{content}</Markdown></div>
    </article>
  );
}
