import { useRef } from "react";
import { motion, useScroll, useSpring } from "framer-motion";
import { Radar, ShieldAlert, TerminalSquare, Scale, BadgeCheck, Loader } from "lucide-react";
import { useApp } from "@/context/AppContext";
import { SKILLS, TIMELINE, CERTS, CERT_STATUS } from "@/i18n";
import { Reveal, Spotlight, Counter, Eyebrow } from "./motion";

export const Section = ({ id, label, title, sub, children, testId, className = "" }) => (
  <section id={id} className={`relative max-w-6xl mx-auto px-5 sm:px-8 pt-32 ${className}`} data-testid={testId}>
    <Reveal>
      <Eyebrow>{label}</Eyebrow>
      {title && <h2 className="mt-5 text-3xl sm:text-5xl font-semibold leading-[1.05] max-w-3xl text-gradient">{title}</h2>}
      {sub && <p className="text-muted-foreground mt-4 max-w-xl text-lg">{sub}</p>}
    </Reveal>
    <div className="mt-12">{children}</div>
  </section>
);

const TOOLS = ["Wazuh", "Microsoft Sentinel", "TheHive", "Cortex", "OpenSearch", "Sysmon", "MITRE ATT&CK", "Python", "KQL", "Docker", "Atomic Red Team", "VirusTotal", "AbuseIPDB", "Kali Linux"];

export const StatsStrip = () => {
  const { t } = useApp();
  return (
    <section className="max-w-6xl mx-auto px-5 sm:px-8 pt-10" data-testid="stats-strip-container">
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        {t.stats.map((s, i) => (
          <Reveal key={i} delay={i * 0.08}>
            <Spotlight className="rounded-2xl glass p-6 h-full" data-testid={`stat-item-${i}`}>
              <div className="text-4xl sm:text-5xl font-semibold tracking-tight text-gradient"><Counter value={s.value} /></div>
              <div className="text-sm text-muted-foreground mt-2">{s.label}</div>
            </Spotlight>
          </Reveal>
        ))}
      </div>
      <div className="mt-14 fade-x overflow-hidden" data-testid="tools-marquee">
        <div className="marquee flex w-max gap-10 font-mono text-sm text-muted-foreground">
          {[...TOOLS, ...TOOLS].map((tl, i) => <span key={i} className="whitespace-nowrap flex items-center gap-10">{tl}<span className="text-primary/50">✦</span></span>)}
        </div>
      </div>
    </section>
  );
};

const ICONS = { siem: Radar, ir: ShieldAlert, script: TerminalSquare, fw: Scale };
const SPANS = ["lg:col-span-2", "", "", "lg:col-span-2"];

export const Skills = () => {
  const { t, lang } = useApp();
  return (
    <Section id="skills" label="Toolkit" title={t.sections.skills} sub={t.sections.skillsSub} testId="skills-section">
      <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3">
        {SKILLS.map((g, i) => {
          const Icon = ICONS[g.key];
          return (
            <Reveal key={g.key} delay={i * 0.08} className={SPANS[i]}>
              <Spotlight className="rounded-2xl glass p-7 h-full" data-testid={`skill-group-${g.key}`}>
                <div className="h-10 w-10 rounded-xl grid place-items-center bg-primary/10 text-primary border border-primary/20"><Icon size={19} /></div>
                <h3 className="mt-5 text-lg font-semibold tracking-tight">{g[lang]}</h3>
                <div className="flex flex-wrap gap-2 mt-4">
                  {g.items.map((it) => <span key={it} className="text-xs px-2.5 py-1 rounded-full border border-foreground/10 bg-foreground/[0.03] text-muted-foreground">{it}</span>)}
                </div>
              </Spotlight>
            </Reveal>
          );
        })}
      </div>
    </Section>
  );
};

export const Timeline = () => {
  const { t, lang } = useApp();
  const ref = useRef(null);
  const { scrollYProgress } = useScroll({ target: ref, offset: ["start 80%", "end 50%"] });
  const scaleY = useSpring(scrollYProgress, { stiffness: 120, damping: 30 });
  return (
    <Section id="experience" label="Experience" title={t.sections.experience} testId="experience-section">
      <div ref={ref} className="relative pl-8 sm:pl-10">
        <div className="absolute left-[7px] sm:left-[11px] top-2 bottom-2 w-px bg-foreground/10" />
        <motion.div style={{ scaleY }} className="absolute left-[7px] sm:left-[11px] top-2 bottom-2 w-px origin-top bg-gradient-to-b from-[hsl(var(--primary))] to-[hsl(var(--accent2))]" />
        <div className="space-y-6">
          {TIMELINE.map((e, i) => {
            const c = e[lang];
            return (
              <Reveal key={i} delay={i * 0.1}>
                <div className="relative" data-testid={`timeline-item-${i}`}>
                  <span className="absolute -left-8 sm:-left-10 top-7 h-[15px] w-[15px] sm:h-[23px] sm:w-[23px] rounded-full border-4 border-background bg-primary shadow-[0_0_16px_hsl(var(--primary)/.6)]" />
                  <Spotlight className="rounded-2xl glass p-6 sm:p-7">
                    <div className="flex flex-wrap items-center gap-3">
                      <span className="font-mono text-xs text-primary">{e.period}</span>
                      <span className="text-[10px] uppercase tracking-wider px-2 py-0.5 rounded-full border border-foreground/10 text-muted-foreground">{e.type === "edu" ? "Education" : "Work"}</span>
                    </div>
                    <h3 className="mt-3 text-xl sm:text-2xl font-semibold tracking-tight">{c.title} <span className="text-muted-foreground font-normal">· {c.org}</span></h3>
                    <p className="text-muted-foreground mt-2 max-w-2xl leading-relaxed">{c.desc}</p>
                  </Spotlight>
                </div>
              </Reveal>
            );
          })}
        </div>
      </div>
    </Section>
  );
};

export const Certs = () => {
  const { t, lang } = useApp();
  return (
    <Section id="certs" label="Credentials" title={t.sections.certs} testId="certs-section">
      <div className="grid sm:grid-cols-2 gap-3">
        {CERTS.map((c, i) => {
          const earned = c.status === "earned";
          return (
            <Reveal key={c.name} delay={i * 0.06}>
              <Spotlight className="rounded-2xl glass p-6 h-full" data-testid={`cert-card-${i}`}>
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <div className="font-mono text-[11px] uppercase tracking-wider text-muted-foreground">{c.issuer}</div>
                    <h3 className="mt-1.5 font-semibold text-lg tracking-tight">{c.name}</h3>
                  </div>
                  <span className={`shrink-0 inline-flex items-center gap-1.5 text-[11px] font-medium px-2.5 py-1 rounded-full border ${earned ? "text-[hsl(var(--accent2))] border-[hsl(var(--accent2)/.3)] bg-[hsl(var(--accent2)/.08)]" : "text-[hsl(var(--warn))] border-[hsl(var(--warn)/.3)] bg-[hsl(var(--warn)/.08)]"}`} data-testid={`cert-status-${i}`}>
                    {earned ? <BadgeCheck size={13} /> : <Loader size={13} className="animate-spin [animation-duration:3s]" />}{CERT_STATUS[lang][c.status]}
                  </span>
                </div>
                <div className="mt-5 h-1 rounded-full bg-foreground/10 overflow-hidden">
                  <motion.div initial={{ width: 0 }} whileInView={{ width: earned ? "100%" : "55%" }} viewport={{ once: true }} transition={{ duration: 1.2, ease: "easeOut" }}
                    className={`h-full rounded-full ${earned ? "bg-gradient-to-r from-[hsl(var(--primary))] to-[hsl(var(--accent2))]" : "bg-[hsl(var(--warn))]"}`} />
                </div>
                <div className="mt-2 font-mono text-[11px] text-muted-foreground">{c.date}</div>
              </Spotlight>
            </Reveal>
          );
        })}
      </div>
    </Section>
  );
};
