import { useEffect, useState } from "react";
import { Link, useParams } from "react-router-dom";
import { ArrowLeft, Printer, Github } from "lucide-react";
import { api } from "@/lib/api";
import { useApp } from "@/context/AppContext";
import { pick } from "@/i18n";
import { MitreChip } from "@/components/site/Projects";
import { ProjectVisual } from "@/components/site/ProjectVisuals";
import { Reveal } from "@/components/site/motion";

const Block = ({ n, label, children, id }) => (
  <Reveal>
    <section className="grid md:grid-cols-[220px_1fr] gap-4 md:gap-10 py-10 border-t border-foreground/10" data-testid={`case-section-${id}`}>
      <div className="font-mono text-xs uppercase tracking-[0.14em] text-muted-foreground"><span className="text-primary">{n}</span>&nbsp; {label}</div>
      <div>{children}</div>
    </section>
  </Reveal>
);

export default function ProjectPage() {
  const { slug } = useParams();
  const { t, lang } = useApp();
  const L = t.caseLabels;
  const [p, setP] = useState(null);
  const [missing, setMissing] = useState(false);
  useEffect(() => {
    api.get(`/projects/${slug}`).then((r) => setP(r.data)).catch(() => setMissing(true));
  }, [slug]);

  if (missing) return <div className="max-w-3xl mx-auto px-5 pt-40 text-2xl" data-testid="project-not-found">404 — <Link to="/" className="text-primary">{t.back}</Link></div>;
  if (!p) return <div className="max-w-3xl mx-auto px-5 pt-40 font-mono text-sm text-muted-foreground caret">loading</div>;

  return (
    <article className="relative max-w-5xl mx-auto px-5 sm:px-8 pt-32" data-testid="project-page">
      <div className="orb w-[500px] h-[400px] -top-20 left-0 bg-[hsl(var(--primary)/.15)] no-print" />
      <div className="relative">
        <div className="no-print flex justify-between mb-12">
          <Link to="/#projects" className="inline-flex items-center gap-2 h-9 px-4 rounded-full glass text-sm hover:text-primary transition-colors" data-testid="case-back-link"><ArrowLeft size={15} />{t.back}</Link>
          <button onClick={() => window.print()} className="inline-flex items-center gap-2 h-9 px-4 rounded-full glass text-sm hover:text-primary transition-colors" data-testid="case-study-print-btn"><Printer size={15} />{t.print}</button>
        </div>
        <Reveal>
          <div className="font-mono text-xs uppercase tracking-[0.16em] text-primary">Case study · {String(p.order).padStart(2, "0")}</div>
          <h1 className="mt-4 text-4xl sm:text-6xl font-semibold leading-[1.03] text-gradient max-w-4xl" data-testid="project-title">{pick(p, "title", lang)}</h1>
          <p className="text-xl text-muted-foreground mt-5 max-w-3xl leading-relaxed">{pick(p, "tagline", lang)}</p>
        </Reveal>
        <Reveal delay={0.1}>
          <div className="mt-12 grid md:grid-cols-[1fr_auto] gap-4">
            <div className="rounded-3xl glass p-6"><ProjectVisual index={(p.order || 1) - 1} /></div>
            <div className="rounded-3xl glass p-6 flex md:flex-col gap-8 justify-center">
              {p.metrics?.map((m) => <div key={m.label}><div className="text-4xl font-semibold text-gradient-accent">{m.value}</div><div className="text-xs text-muted-foreground mt-1">{m.label}</div></div>)}
            </div>
          </div>
        </Reveal>

        <div className="mt-14">
          <Block n="01" id="problem" label={L.problem}><p className="text-lg leading-[1.75] text-foreground/85">{pick(p, "problem", lang)}</p></Block>
          <Block n="02" id="architecture" label={L.architecture}><p className="text-lg leading-[1.75] text-foreground/85">{pick(p, "architecture", lang)}</p></Block>
          <Block n="03" id="detections" label={L.detections}>
            <div className="rounded-2xl border border-foreground/10 bg-card overflow-hidden">
              <div className="flex items-center gap-1.5 px-4 h-9 border-b border-foreground/10"><i className="h-2.5 w-2.5 rounded-full bg-foreground/15" /><i className="h-2.5 w-2.5 rounded-full bg-foreground/15" /><i className="h-2.5 w-2.5 rounded-full bg-foreground/15" /><span className="ml-3 font-mono text-[11px] text-muted-foreground">rules.conf</span></div>
              <div className="p-5 font-mono text-[13px] space-y-4">
                {p.detections?.map((d, i) => (
                  <div key={i}>
                    <div><span className="text-muted-foreground">{String(i + 1).padStart(2, "0")}</span> <span className="text-primary">rule</span> <span className="text-[hsl(var(--accent2))]">"{d.name}"</span></div>
                    <div className="pl-7 text-foreground/75">{d.logic}</div>
                  </div>
                ))}
              </div>
            </div>
          </Block>
          <Block n="04" id="mitre" label={L.mitre}><div className="flex flex-wrap gap-2">{p.mitre?.map((m) => <MitreChip key={m.id} m={m} />)}</div></Block>
          <Block n="05" id="screens" label={L.screens}>
            <div className="grid sm:grid-cols-2 gap-3">
              {[1, 2].map((n) => (
                <div key={n} className="aspect-video rounded-2xl border border-dashed border-foreground/15 grid place-items-center font-mono text-xs text-muted-foreground bg-foreground/[0.02]" data-testid={`screenshot-placeholder-${n}`}>fig.{n} — screenshot coming soon</div>
              ))}
            </div>
          </Block>
          <Block n="06" id="outcome" label={L.outcome}><p className="text-xl leading-relaxed font-medium">{pick(p, "outcome", lang)}</p></Block>
          <Block n="07" id="stack" label={L.stack}>
            <div className="flex flex-wrap gap-2">{p.stack?.map((s) => <span key={s} className="text-sm px-3 py-1 rounded-full glass">{s}</span>)}</div>
            {p.github && <a href={p.github} target="_blank" rel="noreferrer" className="no-print inline-flex items-center gap-2 mt-6 h-10 px-5 rounded-full bg-foreground text-background text-sm font-medium" data-testid="case-github-link"><Github size={15} />{L.repo}</a>}
          </Block>
        </div>
      </div>
    </article>
  );
}
