import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { api } from "@/lib/api";
import { useApp } from "@/context/AppContext";
import { Hero } from "@/components/site/Hero";
import { StatsStrip, Skills, Timeline, Certs, Section } from "@/components/site/Sections";
import { ProjectsGrid } from "@/components/site/Projects";
import { PostRow } from "@/components/site/BlogCards";
import { ContactForm } from "@/components/site/ContactForm";
import { Reveal } from "@/components/site/motion";

export default function Home() {
  const { t } = useApp();
  const [projects, setProjects] = useState([]);
  const [posts, setPosts] = useState([]);
  useEffect(() => {
    api.get("/projects").then((r) => setProjects(r.data));
    api.get("/posts").then((r) => setPosts(r.data));
  }, []);

  return (
    <div data-testid="home-page">
      <Hero />
      <StatsStrip />
      <Skills />
      <ProjectsGrid projects={projects} />
      <Timeline />
      <Certs />
      <Section label="Blog" title={t.sections.blog} sub={t.sections.blogSub} testId="blog-preview-section">
        <div className="grid md:grid-cols-2 gap-3">
          {posts.slice(0, 4).map((p, i) => <Reveal key={p.slug} delay={i * 0.08}><PostRow p={p} /></Reveal>)}
        </div>
        <Link to="/blog" className="inline-flex mt-8 text-sm font-medium text-primary hover:underline underline-offset-4" data-testid="all-posts-link">{t.allPosts} →</Link>
      </Section>
      <ContactForm />
    </div>
  );
}
